@pytest.mark.parametrize('actual', ['execution_result_acquisition', 'scientific_process/execution_result_acquisition', 'hpc_work_planning/execution_result_acquisition', 'hpc_work_planning/hpc_allocation_execution/execution_result_acquisition', 'scientific_process/hpc_work_planning/execution_result_acquisition', 'scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition'], indirect=['actual'], ids=['home=execution_result_acquisition', 'home=scientific_process/execution_result_acquisition', 'home=hpc_work_planning/execution_result_acquisition', 'home=hpc_work_planning/hpc_allocation_execution/execution_result_acquisition', 'home=scientific_process/hpc_work_planning/execution_result_acquisition', 'home=scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition'])
def test_actual_constructor_registry_and_original_configuration(actual):
    v = actual
    b = v.binding
    assert type(b).__module__ == 'gene_annotation_episode.episodic_workflow.root.a103.' + v.home.replace('/', '.') + '.episode'
    assert b.as_record() == {'binding_id': v.home, 'version': b.as_record()['version'], 'configuration': v.configuration}
    assert b.binding_path == v.home and b.roles == ('results',)
    assert b.entry_roles == {'execution_result_acquisition': ('results',), 'scientific_process/execution_result_acquisition': ('results',), 'hpc_work_planning/execution_result_acquisition': (), 'hpc_work_planning/hpc_allocation_execution/execution_result_acquisition': (), 'scientific_process/hpc_work_planning/execution_result_acquisition': (), 'scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition': ()}[v.home]
    assert b.store is v.store and b.tool_registry is v.tools and (b.services is v.services)
    assert v.registry.for_path(v.context.path) is b and v.registry.for_child(v.parent.path, 'results') is b
    assert b.allowed_children(v.context, []) == b.child_roles('results') == ()
    assert b.prepare_assignment(v.parent, 'results', deepcopy(v.assignment), v.runtime._plain(v.context.scope), v.journal.run_id + ':' + v.parent.episode_id + ':0') == v.assignment
    with pytest.raises(ValueError, match='^unknown_execution_episode_role$'):
        b.assignment_schema('launch')
    duplicate = capture(lambda: v.registry.register(b))
    assert duplicate['status'] == 'raised' and duplicate['message'] == 'duplicate_episode_binding_path:' + v.home

