@pytest.mark.parametrize('actual', ['execution_result_acquisition', 'scientific_process/execution_result_acquisition', 'hpc_work_planning/execution_result_acquisition', 'hpc_work_planning/hpc_allocation_execution/execution_result_acquisition', 'scientific_process/hpc_work_planning/execution_result_acquisition', 'scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition'], indirect=['actual'], ids=['home=execution_result_acquisition', 'home=scientific_process/execution_result_acquisition', 'home=hpc_work_planning/execution_result_acquisition', 'home=hpc_work_planning/hpc_allocation_execution/execution_result_acquisition', 'home=scientific_process/hpc_work_planning/execution_result_acquisition', 'home=scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition'])
def test_terminal_completion_and_replay_do_not_reobserve(actual):
    from .results_task_checks import select
    v = actual
    v.state.update(state='completed', returncode=0)
    key, first = select(v, 0, 'execution.results.read', {'path': v.assignment['selector']['path'], 'offset': 0, 'limit': 10})
    assert first['status'] == 'completed'
    body = v.binding._read_result(first['record_refs'][0], v.context.scope)
    assert v.binding._native_results_complete(v.context, [body])
    proof = v.binding.completion_for_action(v.context, key)
    assert proof is not None and v.binding.verify_completion(v.context, proof)
    events = deepcopy(v.events)
    assert asyncio.run(v.binding.execute(v.context, 'execution.results.read', {'path': v.assignment['selector']['path'], 'offset': 0, 'limit': 10}, key)) == first
    assert v.events == events
    _, following = select(v, 1, 'execution.results.status', {})
    assert following['status'] == 'invalid' and following['feedback']['code'] == 'execution_results_assignment_already_completed'
    assert v.events == events

