@pytest.mark.parametrize('actual', ['execution_result_acquisition', 'scientific_process/execution_result_acquisition', 'hpc_work_planning/execution_result_acquisition', 'hpc_work_planning/hpc_allocation_execution/execution_result_acquisition', 'scientific_process/hpc_work_planning/execution_result_acquisition', 'scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition'], indirect=['actual'], ids=['home=execution_result_acquisition', 'home=scientific_process/execution_result_acquisition', 'home=hpc_work_planning/execution_result_acquisition', 'home=hpc_work_planning/hpc_allocation_execution/execution_result_acquisition', 'home=scientific_process/hpc_work_planning/execution_result_acquisition', 'home=scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition'])
def test_saved_reason_keeps_original_completed_outcome_without_reexecution(actual):
    v = actual
    task = make_task(v)
    native = []
    selection = {'kind': 'reason', 'commit': {'original_saved_commit': True}}
    result = {'status': 'completed', 'record_refs': [], 'changed_record_refs': []}
    v.journal.save('runtime_actions', {'episode_id': task.episode_id, 'decision_index': 12, 'action': v.runtime._json(selection), 'result': v.runtime._json(result), 'credit': 3.5})
    task.workflow = SimpleNamespace(run_id=v.journal.run_id, journal=v.journal, execution_binding=None, receive_native_outcome=lambda source, outcome, index: native.append((outcome, index)), receive_outcome=lambda *args: pytest.fail('saved credited reason projected again'), source_credit_view=lambda *args: pytest.fail('saved credited reason repriced'), controller_value=lambda source, index, credit: credit)
    assert asyncio.run(task.execute(selection, 12)) == 3.5 and native == [(result, 12)]
    with pytest.raises(v.runtime.WorkflowError, match='reconstructed selected work changed'):
        asyncio.run(task.execute({'kind': 'reason', 'commit': {'changed': True}}, 12))

@pytest.mark.parametrize('actual', ['execution_result_acquisition', 'scientific_process/execution_result_acquisition', 'hpc_work_planning/execution_result_acquisition', 'hpc_work_planning/hpc_allocation_execution/execution_result_acquisition', 'scientific_process/hpc_work_planning/execution_result_acquisition', 'scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition'], indirect=['actual'], ids=['home=execution_result_acquisition', 'home=scientific_process/execution_result_acquisition', 'home=hpc_work_planning/execution_result_acquisition', 'home=hpc_work_planning/hpc_allocation_execution/execution_result_acquisition', 'home=scientific_process/hpc_work_planning/execution_result_acquisition', 'home=scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition'])
def test_private_decision_state_retains_original_outcome_and_current_credit(actual, monkeypatch):
    v = actual
    task = make_task(v)
    captured = []
    unit = object()
    outcome = {'status': 'invalid', 'record_refs': [], 'changed_record_refs': [], 'feedback': {'code': 'controlled_invalid'}}
    task.last_outcome = outcome
    task.last_outcome_index = 2
    task.feedback = outcome['feedback']
    monkeypatch.setattr(v.binding, 'decision_context', lambda context, view: {'execution_assignment': deepcopy(v.assignment)})
    task.workflow = SimpleNamespace(run_id=v.journal.run_id, inprocess_replay=None, execution_binding=None, journal=v.journal, store=v.store, working_state=lambda source: {'records': []}, local_outcome_preview=lambda outcome, **kwargs: deepcopy(outcome), source_credit_view=lambda source: {'credit': 2.5}, receipt_projection=lambda source: False, source_credit_binding=lambda source: {'kind': 'operational'}, pending_work=lambda source: [], delivery_status=lambda episode: [], controller_binding={}, catalog=lambda *args, **kwargs: [], knowledge=SimpleNamespace(context=lambda: {}), job_episode_options=lambda source: [], extra_report_sources=lambda source: {}, specialist=lambda source: v.binding, binding_context=lambda source: v.context, is_scientific_source=lambda source: False, tools=object(), action_schema=lambda source: {})

    async def call(context, schema):
        captured.append(context)
        return ({}, 0, context, schema)
    task.call = call
    task.apply_response = lambda *args: unit
    view = SimpleNamespace(units_consumed=0, controller_state={}, child_reports=(), model_inputs=lambda state, **kwargs: state)
    assert asyncio.run(task.next(view)) is unit
    assert captured[0]['current_credit'] == 2.5 and captured[0]['last_local_outcome'] == outcome
    assert captured[0]['feedback'] == outcome['feedback'] and captured[0]['execution_assignment'] == v.assignment

