@pytest.mark.parametrize('actual', ['execution_result_acquisition', 'scientific_process/execution_result_acquisition', 'hpc_work_planning/execution_result_acquisition', 'hpc_work_planning/hpc_allocation_execution/execution_result_acquisition', 'scientific_process/hpc_work_planning/execution_result_acquisition', 'scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition'], indirect=['actual'], ids=['home=execution_result_acquisition', 'home=scientific_process/execution_result_acquisition', 'home=hpc_work_planning/execution_result_acquisition', 'home=hpc_work_planning/hpc_allocation_execution/execution_result_acquisition', 'home=scientific_process/hpc_work_planning/execution_result_acquisition', 'home=scientific_process/hpc_work_planning/hpc_allocation_execution/execution_result_acquisition'])
def test_actual_provider_rendering_preserves_recognition_frames_priority_and_json(actual):
    task = make_task(actual)
    providers = own('providers')
    frames = own('decision_context')
    original = object.__new__(providers._SessionConnection)
    original.scientific_prompt_states = {}
    proposed = object.__new__(providers._SessionConnection)
    proposed.scientific_prompt_states = {}
    calls = []

    async def complete(episode, role, instructions, context, schema, **kwargs):
        calls.append(bool(kwargs))
        return proposed._presentation(episode, role, instructions, context, **kwargs)
    task.workflow = SimpleNamespace(provider=SimpleNamespace(complete=complete, complete_with_presentation=complete), specialist=lambda source: actual.binding)
    instructions = frames.INSTRUCTIONS + '\nAfter its decision_lookup_result arrives'
    selected = {'selected_execution_task': {'version': 'selected_execution_task_v1', 'scientific_question': 'Original controlled question', 'selected_tool_info': [], 'requests': [{'resource_id': 'selected-api', 'resource': {'kind': 'api'}, 'job': {'original': True}}]}}
    api = {**selected, 'execution_assignment': deepcopy(actual.api_assignment), 'api_service': 'ncbi_blast', 'api_request': deepcopy(actual.api_assignment['request'])}

    def bootstrap(state, **extra):
        return {'version': frames.VERSION, 'kind': 'decision_bootstrap', 'base_revision': None, 'revision': frames.revision(state), 'fields': state, 'removed_fields': [], **extra}
    published = {**selected, 'scientific_process': {'evidence_axis': {'instruction_status': 'published_investigation_instructions', 'investigation_instructions': 'Original published instruction'}}}
    changed = {**selected, 'current_credit': 2.5}
    stripped = {'current_credit': 2.5}
    contexts = [(selected, True), (api, False), ({}, False), ({'saved_minimal_context': True}, False), ({**selected, 'hpc_commission': {'objective': 'original higher-priority HPC task'}}, False), (published, False), (bootstrap({}), False), (bootstrap(selected), False), (bootstrap(selected, restored_public_exchanges=[{'lookup_result': {'original_result': 'retained'}}], restored_pending_decision_index=4), False), ({'version': frames.VERSION, 'kind': 'decision_update', 'base_revision': frames.revision(selected), 'revision': frames.revision(changed), 'fields': {'current_credit': 2.5}, 'removed_fields': []}, False), ({'version': frames.VERSION, 'kind': 'decision_lookup_result', 'result': {'original_lookup': True}}, False), ({'version': frames.VERSION, 'kind': 'decision_update', 'base_revision': frames.revision(changed), 'revision': frames.revision(stripped), 'fields': {}, 'removed_fields': ['selected_execution_task']}, False), ({'version': frames.VERSION, 'kind': 'decision_lookup_result', 'result': {'without_base': True}}, False)]
    for context, explicit in contexts:
        expected = original._presentation(task.episode_id, 'REASONING', instructions, deepcopy(context))
        if hasattr(task, 'complete_decision'):
            result = asyncio.run(task.complete_decision(instructions, deepcopy(context), {}))
            assert calls[-1] is explicit
        else:
            result = asyncio.run(complete(task.episode_id, 'REASONING', instructions, deepcopy(context), {}))
            assert calls[-1] is False
        assert result == expected and proposed.scientific_prompt_states == original.scientific_prompt_states
        if context in ({}, {'saved_minimal_context': True}):
            assert result == (json.dumps(context, allow_nan=False), instructions)
    missing = {'version': frames.VERSION, 'kind': 'decision_update', 'base_revision': frames.revision(selected), 'revision': frames.revision(selected), 'fields': selected, 'removed_fields': []}
    with pytest.raises(TypeError, match='^previous_model_state_requires_object$') as prior:
        original._presentation(task.episode_id, 'REASONING', instructions, missing)
    with pytest.raises(TypeError, match='^previous_model_state_requires_object$') as following:
        if hasattr(task, 'complete_decision'):
            asyncio.run(task.complete_decision(instructions, missing, {}))
        else:
            asyncio.run(complete(task.episode_id, 'REASONING', instructions, missing, {}))
    assert type(prior.value) is TypeError and str(prior.value) == 'previous_model_state_requires_object'
    assert type(following.value) is TypeError and str(following.value) == 'previous_model_state_requires_object'

